import{_ as s,l as i,o as a,c as n,v as t,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"vDSO","description":"","frontmatter":{"title":"vDSO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vdso.md","filePath":"cs/vdso.md","lastUpdated":1789023840000}'),h={name:"cs/vdso.md"};function A(E,e,m,_,v,u){const o=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="vdso" tabindex="-1">vDSO <a class="header-anchor" href="#vdso" aria-label="Permalink to &quot;vDSO&quot;">​</a></h1><div class="epigraph"><p>内核可以把少数只读、无副作用的服务映进用户地址空间，让进程不必每次为读时钟而陷入。</p><footer>—— 据 Love, Linux Kernel Development；Bovet and Cesati, Understanding the Linux Kernel 整理</footer></div><p><a href="/cs/syscall-abi">上一课</a>钉死：改内核状态必须按 ABI 陷入。读单调时钟、读 <code>getcpu</code> 这类查询若也每次切特权，<a href="/cs/scheduling-metrics">调度指标</a>里的切换税会变成热点。缺口不是新的调用号，而是：内核能否映射一页<strong>用户可执行、内核只写</strong>的代码与数据，让部分查询在用户态完成。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>clock_gettime</code> 若走完整陷入，保存寄存器、查表、返回，成本远高于读一个计数器。硬件已有用户可读的计时寄存器时，仍要把「此刻的时间基」与校准常数交给用户。缺口是这份由内核维护、用户只读的页面——vDSO（虚拟动态共享对象），不是再发明一条特权指令。</p><p>本课不把 VDSO 的 ELF 布局和每个符号写完。</p><p><span class="marginnote">vDSO 仍是内核提供的实现：数据由内核在时钟中断或时间保持路径里更新。用户程序跳进的是映射进来的函数，不是自己写的特权代码。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核在每个用户地址空间映入固定或随机的 vDSO 页：代码做序列化读，数据是时间基、周期、当前 CPU 提示。用户库先解析该页上的符号；能在用户态完成则跳转，否则退回上一课的陷入 ABI。写入时间基仍只发生在内核；用户页表里该页不可写。</p>',9)),(a(),l(p,null,{default:r(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E7%94%A8%E6%88%B7%E8%AF%BB%E6%97%B6%E9%92%9F%22%5D%20--%3E%20VDSO%5B%22vDSO%20%E9%A1%B5%3A%20%E5%8F%AA%E8%AF%BB%E6%95%B0%E6%8D%AE%E5%8A%A0%E4%BB%A3%E7%A0%81%22%5D%0A%20%20VDSO%20--%3E%20FAST%5B%22%E7%94%A8%E6%88%B7%E6%80%81%E5%AE%8C%E6%88%90%22%5D%0A%20%20APP%20--%3E%20TRAP%5B%22%E6%97%A0%E6%B3%95%E5%AE%8C%E6%88%90%E5%88%99%E9%99%B7%E5%85%A5%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p><a href="/cs/paging-vm">分页</a>已经能把同一物理页映进每个进程；本课只使用「用户不可写」。ASLR 如何随机该页，是更后的安全课，这里只承认可以随机。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>vDSO 把 ABI 分成两层：真正改状态的仍陷入；无副作用的快路径不切特权。它不削弱<a href="/cs/kernel-user">内核与用户态</a>的门：用户仍然不能改页表、不能关中断。若时间基更新与用户读交错，实现用序列计数或类似手段让读到的是完整快照——细节是同步课的对象，本课只要求「读到的不是撕裂的一半」。</p><p>不是所有调用都能进 vDSO：打开文件、改页表、发送信号都必须陷入。本课名单极短。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 vsyscall 页的历史兼容写成另一课，不讨论伪造 vDSO 符号。也不把 GPU 时间戳请进来。安全课会关心该页是否可执行、是否可写；主干只要求内核只写、用户只读执行。</p><p>后课默认：读时钟一类查询可以免陷入；一旦要保存完整用户寄存器并进入内核，就必须有一份<strong>陷阱帧</strong>。下一课钉 trapframe。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>vDSO：内核映入用户的只读快路径，不改「改状态必须陷入」。</li><li>时间基仍由内核更新；用户不可写该页。</li><li>真正进入内核时如何保存现场，是下一课。</li><li>出处：Love, <em>LKD</em>；Bovet and Cesati, <em>Understanding the Linux Kernel</em>。</li></ul>',9))])}const B=s(h,[["render",A]]);export{D as __pageData,B as default};
